import{_ as e,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"内在价值 Intrinsic Value","description":"巴菲特投资哲学的核心：如何计算企业的内在价值","frontmatter":{"title":"内在价值 Intrinsic Value","description":"巴菲特投资哲学的核心：如何计算企业的内在价值"},"headers":[],"relativePath":"02_concepts/intrinsic-value.md","filePath":"02_concepts/intrinsic-value.md"}'),r={name:"02_concepts/intrinsic-value.md"};function p(h,t,n,s,i,d){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="内在价值-intrinsic-value" tabindex="-1">内在价值 Intrinsic Value <a class="header-anchor" href="#内在价值-intrinsic-value" aria-label="Permalink to &quot;内在价值 Intrinsic Value&quot;">​</a></h1><blockquote><p><strong>内在价值</strong>是<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>投资哲学的基石，也是他一切投资决策的核心出发点。在<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>看来，投资的本质就是用低于内在价值的价格买进资产，从而获得安全边际的保护。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1985年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">华盛顿邮报案例：内在价值4-5亿 vs 市价1亿</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1994年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">现金流折现法的经典阐述</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2000年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">内在价值计算逻辑详解</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2007年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">市场价格与内在价值的背离</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">金融危机中内在价值的投资机会</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2010年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;"><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>的内在价值评估方法</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2019年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">账面价值与内在价值的长期关系</td></tr></tbody></table><hr><h2 id="一、什么是内在价值" tabindex="-1">一、什么是内在价值 <a class="header-anchor" href="#一、什么是内在价值" aria-label="Permalink to &quot;一、什么是内在价值&quot;">​</a></h2><p>内在价值（Intrinsic Value）是指一家企业在剩余存续期内能够产生的现金流的贴现值。它是一个<strong>估算值</strong>，而非精确数字。</p><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1994年致股东信中对此有经典阐述：</p><blockquote><p>&quot;内在价值是一个经济概念，是一家企业在剩余存续期内能够产生的现金流的贴现值。现金流折现法是评估某项业务或金融资产内在价值的唯一逻辑方法。内在价值的计算既不是精确的科学，甚至也算不上可靠的艺术。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1994年致股东信</p></blockquote><p>内在价值取决于三个关键变量：</p><ol><li><strong>存续期</strong>——企业还能存活多久</li><li><strong>现金流</strong>——企业未来能产生多少现金</li><li><strong>贴现率</strong>——用多大利率把未来现金流折算成现值</li></ol><hr><h2 id="二、按十年分块-内在价值理念的演进" tabindex="-1">二、按十年分块：内在价值理念的演进 <a class="header-anchor" href="#二、按十年分块-内在价值理念的演进" aria-label="Permalink to &quot;二、按十年分块：内在价值理念的演进&quot;">​</a></h2><h3 id="🏛️-合伙基金时期-1956-1969" tabindex="-1">🏛️ 合伙基金时期（1956-1969） <a class="header-anchor" href="#🏛️-合伙基金时期-1956-1969" aria-label="Permalink to &quot;🏛️ 合伙基金时期（1956-1969）&quot;">​</a></h3><p>这一时期<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>完全师从<a href="/04_people/本·格雷厄姆.html">格雷厄姆</a>，内在价值计算主要基于净流动资产（Net-Net）法——将企业视作待清算资产包，用流动资产减去全部负债。</p><blockquote><p>&quot;投资的本质是用五角钱买一元钱的东西。这就是安全边际的核心含义。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1958年致股东信</p></blockquote><p>这一时期的典型案例是买入桑伯恩地图公司（Sanborn Map），其持有的有价证券市值已超过整个公司的估值。</p><hr><h3 id="📈-转型时期-1970-1979" tabindex="-1">📈 转型时期（1970-1979） <a class="header-anchor" href="#📈-转型时期-1970-1979" aria-label="Permalink to &quot;📈 转型时期（1970-1979）&quot;">​</a></h3><p>1970年代<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>开始从&quot;捡烟蒂&quot;转向购买优质企业，但内在价值仍是核心标准。</p><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1985年致股东信中坦诚回顾了这一转变：</p><blockquote><p>&quot;1973年我们买华盛顿邮报，整个市场价值才1亿美元，我们算出来内在价值就值4-5亿，当时所有机构都不买，因为有效市场理论说市场永远对，所以这么便宜肯定错了。结果我们买了，现在持股市值2.21亿，成本才1,060万，赚了20多倍。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1985年致股东信</p></blockquote><hr><h3 id="🌟-成熟期-1980-1989" tabindex="-1">🌟 成熟期（1980-1989） <a class="header-anchor" href="#🌟-成熟期-1980-1989" aria-label="Permalink to &quot;🌟 成熟期（1980-1989）&quot;">​</a></h3><p>1980年代<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>形成了成熟的内在价值框架，并将这一理念与好企业结合起来。</p><p><strong>1987年</strong>股灾之后，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>再次强调：</p><blockquote><p>&quot;短期来看，市场是投票机；长期来看，市场是称重机。最后企业怎么样，价值一定会体现，哪怕晚一点，没关系，便宜的时候你还能多买。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1987年致股东信</p></blockquote><p><strong>1988年</strong>首次买入可口可乐，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>明确表示：&quot;我们买了杰出企业杰出管理层，我们最喜欢持有期限就是永远。&quot;</p><p><strong>1989年</strong>是重要转折——<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>宣布&quot;双重收益&quot;时代结束：</p><blockquote><p>&quot;过去我们同时享受两种收益：持仓公司内在价值增长 + 市场定价纠正（估值修复）。未来只能获得&#39;单一收益&#39;——业务增长本身。估值纠正已完成。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1989年致股东信</p></blockquote><hr><h3 id="🔍-精确化时期-1990-1999" tabindex="-1">🔍 精确化时期（1990-1999） <a class="header-anchor" href="#🔍-精确化时期-1990-1999" aria-label="Permalink to &quot;🔍 精确化时期（1990-1999）&quot;">​</a></h3><p>这一时期<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对内在价值的阐述更加系统和精准。</p><p><strong>1990年</strong>首次提出&quot;透视盈利&quot;（Look-Through Earnings）概念，弥补GAAP会计的不足：</p><blockquote><p>&quot;GAAP只记录我们收到的股息，但被投资企业的留存盈利同样在为我们创造价值。我们需要透视盈利来理解真正的经济收益。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1990年致股东信</p></blockquote><p><strong>1993年</strong>对内在价值与安全边际的关系说得最清楚：</p><blockquote><p>&quot;对于大多数投资者来说重要的不是他们知道多少，而是他们如何现实地定义自己不知道什么。安全边际是投资成功的基石。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1993年致股东信</p></blockquote><p><strong>1994年</strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>说出了规模诅咒：</p><blockquote><p>&quot;伯克希尔净资产已达119亿美元，需要至少1亿美元的投资机会才能产生影响。我们已经从一个甜蜜区进入了几乎没有球可打的状态。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1994年致股东信</p></blockquote><p><strong>1996年</strong>对市场价格与内在价值的关系做了精准总结：</p><blockquote><p>&quot;股票暂时超越或落后于业务，少数卖家或买家会获得超额收益，损害交易对手。长期来看，市场价格会反映内在价值。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1996年致股东信</p></blockquote><hr><h3 id="⚖️-成熟与告别-2000-2025" tabindex="-1">⚖️ 成熟与告别（2000-2025） <a class="header-anchor" href="#⚖️-成熟与告别-2000-2025" aria-label="Permalink to &quot;⚖️ 成熟与告别（2000-2025）&quot;">​</a></h3><p><strong>2003年</strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对内在价值的表述最为坦白：</p><blockquote><p>&quot;我们的股东可以以极低成本通过指数基金购买标普500。除非我们未来每股内在价值的增长超过标普的表现，否则查理和我在你们自己能做到的基础上不会增加任何价值。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2003年致股东信</p></blockquote><p><strong>2010年</strong>：</p><blockquote><p>&quot;我们继续坚持采用内在价值作为我们评估的标准，而不是账面价值。无论我们为收购支付了多高的溢价，只要你确定企业的内在价值稳步增长，你就是一项好的投资。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2010年致股东信</p></blockquote><p><strong>2019年</strong>：</p><blockquote><p>&quot;我们业务和债券的内在价值，远超伯克希尔的账面价值……随着时间推移，账面价值会越来越接近内在价值，尽管这并非直线前进的过程。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2019年致股东信</p></blockquote><hr><h2 id="三、安全边际-内在价值的实践意义" tabindex="-1">三、安全边际：内在价值的实践意义 <a class="header-anchor" href="#三、安全边际-内在价值的实践意义" aria-label="Permalink to &quot;三、安全边际：内在价值的实践意义&quot;">​</a></h2><p>知道内在价值后，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>并不会在价格等于内在价值时买入。他坚持核心原则：<strong>安全边际（Margin of Safety）</strong>。</p><blockquote><p>&quot;当一家强势公司遇到暂时性重大问题时，要提供有吸引力的买入机会，我们就应该做好准备。经济意外是常有的事，但人类恐慌则更加频繁。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2016年致股东信</p></blockquote><hr><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>说明</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>企业在剩余存续期内产生的现金流贴现值</td></tr><tr><td><strong>计算方法</strong></td><td>现金流折现法（DCF）</td></tr><tr><td><strong>关键变量</strong></td><td>存续期、自由现金流、贴现率</td></tr><tr><td><strong>两大时代</strong></td><td>双重收益时代（1989年前）→ 单一收益时代（1989年后）</td></tr><tr><td><strong>局限性</strong></td><td>本质上是主观估计，不是精确数字</td></tr></tbody></table><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./moat.html">护城河 (Moat)</a> — 理解企业如何持续创造价值</li><li><a href="./circle-of-competence.html">能力圈 (Circle of Competence)</a> — 只投资真正理解的企业</li><li><a href="./safety-margin.html">安全边际 (Safety Margin)</a> — 买入价应显著低于内在价值</li></ul>',60)])])}const q=e(r,[["render",p]]);export{c as __pageData,q as default};
